'use strict';
const {test}=require('node:test');const assert=require('node:assert/strict');const {view}=require('./radar-view-model');const {emptyGarage,addVehicle}=require('./garage');
const vehicle={id:'v1',name:'Ma voiture',fuel:'Gazole',consumption:6,tankCapacity:50,fillPercent:80,illustration:'berline'};
const garage=addVehicle(emptyGarage(),vehicle);
const stations=[{id:'1',name:'A',price:1.6},{id:'2',name:'B',price:1.7},{id:'3',name:'C',price:1.8}];
const a={id:'1',totalCost:65.2,distanceRoundTripKm:8.56,durationOutboundMinutes:7.2};
const b={id:'2',totalCost:69.3,distanceRoundTripKm:11,durationOutboundMinutes:null};
const ranking={top:[a],calculated:[a,b],uncalculated:['3'],unavailable:[],certified:true};
test('empty garage asks for vehicle',()=>{assert.equal(view({garage:emptyGarage()}).status,'needs_vehicle')});
test('default car and remembered gauge',()=>{const x=view({garage,ranking,stations});assert.equal(x.fillPercent,80);assert.equal(x.vehicle.id,'v1')});
test('three prominent values',()=>{const x=view({garage,ranking,stations});assert.equal(x.top[0].totalCost,65.2);assert.equal(x.top[0].distanceRoundTripKm,8.6);assert.equal(x.top[0].durationOutboundMinutes,8)});
test('more hidden by default',()=>{const x=view({garage,ranking,stations});assert.equal(x.more.length,0);assert.equal(x.hiddenCount,2)});
test('more shows both measured and unmeasured',()=>{const x=view({garage,ranking,stations,showMore:true});assert.equal(x.more.length,2);assert.equal(x.more[1].canCalculate,true)});
test('missing time is null not fabricated',()=>{const x=view({garage,ranking,stations,showMore:true});assert.equal(x.more[0].durationOutboundMinutes,null)});
test('unverified clearly labelled',()=>{const x=view({garage,ranking:{...ranking,certified:false},stations});assert.equal(x.status,'unverified');assert.match(x.message,/provisoire/)});
test('missing ranking rejected',()=>assert.throws(()=>view({garage,stations}),/Classement/));
test('invalid fill rejected',()=>assert.throws(()=>view({garage,ranking,fillPercent:0}),/Pourcentage/));
test('unknown selected vehicle returns add prompt',()=>{const x=view({garage,ranking,selectedVehicleId:'bad'});assert.equal(x.status,'needs_vehicle')});
test('no station metadata still renders',()=>{const x=view({garage,ranking});assert.equal(x.top[0].name,'Station-service')});
test('unavailable station remains accessible',()=>{const x=view({garage,stations,ranking:{top:[],calculated:[],uncalculated:[],unavailable:['3'],certified:false},showMore:true});assert.equal(x.more[0].id,'3')});
